mapper.select:
SELECT conversation.id AS conversation_id, conversation.title, conversation.module_id, module.name AS module_name, 'completed' AS status, conversation.closed_at AS completed_at FROM group_conversation conversation JOIN trpg_completion completion ON completion.conversation_id = conversation.id LEFT JOIN coc_module module ON module.id = conversation.module_id WHERE conversation.user_world_id = #{userWorldId} AND conversation.mode = 'trpg' AND AND EXISTS (SELECT 1 FROM group_chat_member member WHERE member.conversation_id = conversation.id AND member.actor_type = 'character' AND member.actor_id = #{characterId})
AND (conversation.closed_at, conversation.id) < (#{beforeCompletedAt}, #{beforeConversationId})
ORDER BY conversation.closed_at DESC, conversation.id DESC LIMIT #{limit}
